mapper.select:
SELECT IFNULL(count(*), 0)
FROM COMMENTS
WHERE feed_code = #{feedCode}

SELECT c.code, c.content, c.created_at, c.updated_at, mp.code AS m_code, mp.id AS m_id, mp.ranking AS m_ranking, mp.rating AS m_rating, mp.path AS m_profile_image, IFNULL(cnt_like.cnt, 0) AS count_comment_like, IF(my_like.cmt_code IS NOT NULL, 1, 0) AS liked_yn FROM COMMENTS c
JOIN ( SELECT m.code, m.id, i.path, m.ranking, m.rating FROM MEMBER_ACCOUNT m LEFT JOIN IMAGES i ON m.code = i.target_code AND i.TYPE = 'profile' ) AS mp ON mp.code = c.mem_code
LEFT JOIN ( SELECT cl.cmt_code, count(*) AS cnt FROM COMMENT_LIKE cl GROUP BY cl.cmt_code ) AS cnt_like ON cnt_like.cmt_code = c.code
LEFT JOIN COMMENT_LIKE my_like ON my_like.cmt_code = c.code AND my_like.mem_code = #{memberCode}
WHERE c.feed_code = #{feedCode} AND c.status = 'active' AND c.delete_yn = 0 ORDER BY c.created_at DESC, c.code DESC
LIMIT #{offset}, #{perPage}
